/**
 * Single registry mapping every user-provided PNG in public/icons/ to its UI slot.
 * Paths contain spaces (and a trailing space in "options in nuur "), plus Cyrillic
 * names, so every URL goes through encodeURI.
 *
 * Matching was done by visually comparing each crop against docs/screenshots.
 * Files in public/icons/derived/ are generated by scripts/derive-icons.mjs.
 */
export const icon = (relPath: string) => encodeURI(`/icons/${relPath}`);

const NUUR = "options in nuur /"; // trailing space is part of the folder name
const NEMELT = "optoins in nemelt/";
const PROFILE = "icons in profile/";

/** Floating draggable AI helper (ai icon.jpg). */
export const AI_ICON = icon("ai icon.jpg");

/** Bottom nav center FAB (qr scanner icon.png, masked to a circle). */
export const QR_FAB = icon("derived/qr-fab.png");
export const QR_FAB_ORIGINAL = icon("qr scanner icon.png");

/** e-apostille story card that leads the Үйлчилгээ tab (screen_08). */
export const SERVICES_STORY = icon("үйлчилгээ.png");

/**
 * Хөтөч carousel cards (screen_01 / screen_03). Each PNG is the full card,
 * background + title + illustration, so it is rendered edge to edge.
 * "children" (Хүүхэд) has no crop and uses an SVG card instead.
 */
export const GUIDE_CARDS: Record<string, string> = {
  military: icon(`${NUUR}screen_01 copy.png`),
  documents: icon(`${NUUR}screen_01 copy 2.png`),
  "going-abroad": icon(`${NUUR}screen_03 copy.png`),
  health: icon(`${NUUR}screen_03 copy 2.png`),
  loans: icon(`${NUUR}screen_03 copy 3.png`),
};

/** Full ЭРСДЭЛ МЭДЭГДЭХ banner crop (screen_03) and the 3D bell cut from it. */
export const RISK_BANNER_FULL = icon(`${NUUR}screen_03 copy 4.png`);
export const RISK_BELL = icon("derived/risk-bell.png");

